float sdPetal(vec2 p, float len, float wid) {
    p.y -= len * 0.5;
    vec2 q = vec2(p.x / wid, p.y / len);
    return length(q) - 0.5;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float bloom = 0.5 + 0.5 * sin(iTime * 0.4 - 1.5707963);
    bloom = smoothstep(0.0, 1.0, bloom);
    const int PETALS = 8;
    float d = 1e5;
    float len = mix(0.06, 0.5, bloom);
    float wid = mix(0.05, 0.14, bloom);
    for (int i = 0; i < PETALS; i++) {
        float ang = (float(i) / float(PETALS)) * 6.28318 + bloom * 0.6;
        float s = sin(ang);
        float c = cos(ang);
        vec2 p = vec2(c * uv.x + s * uv.y, -s * uv.x + c * uv.y);
        float pd = sdPetal(p, len, wid);
        d = min(d, pd);
    }
    float center = length(uv) - 0.08;
    d = min(d, center);
    vec3 petalCol = mix(vec3(0.9, 0.2, 0.4), vec3(1.0, 0.7, 0.85), bloom);
    vec3 centerCol = vec3(0.95, 0.75, 0.15);
    float cmask = smoothstep(0.01, -0.01, center);
    vec3 col = mix(vec3(0.05, 0.08, 0.05), petalCol, smoothstep(0.02, -0.02, d));
    col = mix(col, centerCol, cmask);
    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float r = length(uv);
    float a = atan(uv.y, uv.x);
    float bloom = smoothstep(0.0, 1.0, 0.5 + 0.5 * sin(iTime * 0.35));
    const int LAYERS = 4;
    vec3 col = vec3(0.03, 0.05, 0.03);
    for (int i = 0; i < LAYERS; i++) {
        float fi = float(i);
        float layerBloom = clamp(bloom * 1.4 - fi * 0.15, 0.0, 1.0);
        float petals = 5.0 + fi;
        float edge = mix(0.03, 0.45 - fi * 0.05, layerBloom) * (0.7 + 0.3 * cos(petals * a + fi * 1.7));
        float mask = smoothstep(edge, edge - 0.03, r - fi * 0.02);
        vec3 pcol = palette(fi / float(LAYERS) + bloom * 0.2, vec3(0.6, 0.3, 0.4), vec3(0.4, 0.3, 0.3), vec3(1.0, 1.0, 0.5), vec3(0.0, 0.2, 0.4));
        col = mix(col, pcol, mask * (1.0 - fi * 0.15));
    }
    float centerMask = smoothstep(0.1, 0.06, r);
    col = mix(col, vec3(0.9, 0.7, 0.2), centerMask);
    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        v += a * noise(p);
        p *= 2.0;
        a *= 0.5;
    }
    return v;
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float bloom = smoothstep(0.0, 1.0, 0.5 + 0.5 * sin(iTime * 0.3));
    float r = length(uv);
    float a = atan(uv.y, uv.x);
    vec2 warpUV = uv * 3.0 + vec2(cos(a * 6.0 + iTime * 0.5), sin(a * 6.0 + iTime * 0.5)) * 0.3 * bloom;
    vec2 q = vec2(fbm(warpUV + iTime * 0.15), fbm(warpUV + vec2(5.2, 1.3) - iTime * 0.1));
    vec2 warped = warpUV + 1.5 * q * bloom;
    float n = fbm(warped);
    float petalMask = 1.0 - smoothstep(mix(0.05, 0.55, bloom), mix(0.08, 0.6, bloom) + 0.05, r + 0.05 * sin(a * 6.0 + n * 3.0));
    vec3 base = palette(n + bloom * 0.3, vec3(0.6, 0.25, 0.35), vec3(0.4, 0.35, 0.3), vec3(1.0, 0.8, 0.6), vec3(0.0, 0.1, 0.25));
    vec3 col = mix(vec3(0.04, 0.06, 0.05), base, petalMask);
    float centerMask = smoothstep(0.09, 0.05, r);
    col = mix(col, vec3(0.85, 0.65, 0.15), centerMask);
    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

mat2 rot(float a) {
    float s = sin(a);
    float c = cos(a);
    return mat2(c, -s, s, c);
}

float sdEllipsoid(vec3 p, vec3 r) {
    return (length(p / r) - 1.0) * min(r.x, min(r.y, r.z));
}

float map(vec3 p, float openA) {
    float d = p.y + 0.5;
    const int PETALS = 6;
    for (int i = 0; i < PETALS; i++) {
        float ang = float(i) / float(PETALS) * 6.28318;
        vec3 q = p;
        q.xz = rot(ang) * q.xz;
        vec2 yz = rot(openA) * q.yz;
        q.yz = yz;
        q.x -= 0.35;
        float pd = sdEllipsoid(q, vec3(0.32, 0.05, 0.14));
        d = min(d, pd);
    }
    float center = length(p - vec3(0.0, -0.05, 0.0)) - 0.15;
    d = min(d, center);
    return d;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float bloom = smoothstep(0.0, 1.0, 0.5 + 0.5 * sin(iTime * 0.3));
    float openA = mix(1.4, 0.05, bloom);
    vec3 ro = vec3(0.0, 0.9, 1.6);
    vec3 rd = normalize(vec3(uv, -1.4));
    vec2 ryz = rot(-0.55) * rd.yz;
    rd.yz = ryz;
    vec3 col = vec3(0.02, 0.03, 0.05);
    float t = 0.0;
    bool hit = false;
    vec3 p = ro;
    const int STEPS = 48;
    for (int i = 0; i < STEPS; i++) {
        p = ro + rd * t;
        float d = map(p, openA);
        if (d < 0.001) {
            hit = true;
            break;
        }
        t += d * 0.7 + 0.001;
        if (t > 8.0) break;
    }
    if (hit) {
        vec2 e = vec2(0.001, 0.0);
        vec3 n = normalize(vec3(
            map(p + e.xyy, openA) - map(p - e.xyy, openA),
            map(p + e.yxy, openA) - map(p - e.yxy, openA),
            map(p + e.yyx, openA) - map(p - e.yyx, openA)
        ));
        vec3 lightDir = normalize(vec3(0.5, 0.8, 0.3));
        float diff = clamp(dot(n, lightDir), 0.0, 1.0);
        float petalZone = step(-0.03, p.y);
        vec3 base = mix(mix(vec3(0.9, 0.2, 0.45), vec3(1.0, 0.85, 0.9), bloom), vec3(0.95, 0.75, 0.2), petalZone);
        col = base * (0.3 + 0.7 * diff);
    }
    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

vec2 hash2(vec2 p) {
    p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
    return fract(sin(p) * 43758.5453123);
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

float voronoi(vec2 x, float t) {
    vec2 n = floor(x);
    vec2 f = fract(x);
    float md = 8.0;
    for (int j = -1; j <= 1; j++) {
        for (int i = -1; i <= 1; i++) {
            vec2 g = vec2(float(i), float(j));
            vec2 o = hash2(n + g);
            o = 0.5 + 0.5 * sin(t + 6.2831 * o);
            vec2 r = g + o - f;
            float d = dot(r, r);
            md = min(md, d);
        }
    }
    return sqrt(md);
}

