    float a = atan(uv.y, uv.x);
    vec2 p = vec2(a / 6.28318 * 6.0, r * 6.0 - iTime * 0.15);
    float v = voronoi(p, iTime * 0.5);
    float petalRadius = mix(0.05, 0.5, bloom);
    float mask = smoothstep(petalRadius + 0.05, petalRadius - 0.1, r);
    vec3 col0 = palette(v + bloom * 0.2, vec3(0.55, 0.2, 0.35), vec3(0.45, 0.35, 0.3), vec3(1.0, 0.9, 0.6), vec3(0.0, 0.15, 0.3));
    vec3 col = mix(vec3(0.03, 0.05, 0.04), col0, mask);
    float center = smoothstep(0.1, 0.06, r);
    col = mix(col, vec3(0.9, 0.7, 0.2), center);
    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
