    float pa = ang * count;
    float sharpness = mix(10.0, 1.8, bloomL);
    float lobe = pow(max(cos(pa * 0.5), 0.0), sharpness);
    float outerR = mix(0.04, rMax, bloomL) * mix(0.3, 1.0, lobe);
    return 1.0 - smoothstep(outerR - 0.04, outerR + 0.02, r);
