    vec3 outerCol = palette(n * 0.2 + 0.1, vec3(0.65, 0.2, 0.35), vec3(0.35, 0.3, 0.3), vec3(1.0, 0.7, 0.6), vec3(0.0, 0.15, 0.3));
    vec3 innerCol = palette(n * 0.2 + 0.5, vec3(0.7, 0.3, 0.4), vec3(0.3, 0.3, 0.25), vec3(1.0, 0.9, 0.6), vec3(0.05, 0.05, 0.2));
