    p.xy = rot(theta) * p.xy;
    vec3 s = vec3(0.42, 0.09, 0.16);
    vec3 q = p / s;
    return (length(q) - 1.0) * min(min(s.x, s.y), s.z);
}

float map(vec3 p, float bloom) {
    float d = 1e5;
    const int N = 6;
    float theta = mix(1.5708, 0.0, bloom);
