        float phi = float(i) / float(N) * 6.28318;
        float sp = sin(phi);
        float cp = cos(phi);
        vec3 q = p;
        q.xz = mat2(cp, -sp, sp, cp) * q.xz;
        q.x -= 0.05;
        float pd = sdPetal(q, theta);
        d = min(d, pd);
    }
    float center = length(p - vec3(0.0, 0.02, 0.0)) - 0.12;
    d = min(d, center);
    return d;
}

