        float dy = sdPetals(uv + vec2(0.0, e), bloom) - sdPetals(uv - vec2(0.0, e), bloom);
        vec3 nrm = normalize(vec3(dx, dy, e * 2.0));
        vec3 lightDir = normalize(vec3(0.4, 0.6, 0.7));
        float shade = 0.4 + 0.6 * max(dot(nrm, lightDir), 0.0);

        float ang = atan(uv.y, uv.x);
