        vec3 hueCol = palette(hue, vec3(0.8, 0.4, 0.5), vec3(0.2, 0.35, 0.3), vec3(1.0, 1.0, 0.6), vec3(0.0, 0.15, 0.3));
        vec3 tint = mix(hueCol, vec3(1.0, 0.9, 0.93), bloom * 0.5);
        tint *= shade;

        float fade = 1.0 - fi / float(TRAILS);
        col = mix(col, tint, fill * fade * 0.6);
    }
    float r = length(uv);
    float centerMask = smoothstep(0.1, 0.05, r);
    col = mix(col, vec3(0.95, 0.8, 0.25), centerMask);
