vec2 sdPetalsId(vec2 uv, float bloom) {
    const int PETALS = 6;
    float d = 1e5;
    float id = 0.0;
    for (int i = 0; i < PETALS; i++) {
        float ang = float(i) / float(PETALS) * 6.28318;
        float s = sin(ang);
        float c = cos(ang);
        vec2 p = vec2(c * uv.x + s * uv.y, -s * uv.x + c * uv.y);
        p.y -= mix(0.03, 0.3, bloom) * 0.5;
        vec2 q = vec2(p.x / mix(0.04, 0.12, bloom), p.y / mix(0.06, 0.32, bloom));
        float dd = length(q) - 0.5;
        if (dd < d) {
            d = dd;
            id = float(i);
        }
    }
    return vec2(d, id);
}

