float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        v += a * noise(p);
        p *= 2.0;
        a *= 0.5;
    }
    return v;
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float bloom = smoothstep(0.0, 1.0, 0.5 + 0.5 * sin(iTime * 0.35));

    float r = length(uv);
    float theta = atan(uv.y, uv.x);
    float n = 6.0;

    vec2 warp = vec2(fbm(uv * 3.0 + iTime * 0.05), fbm(uv * 3.0 - iTime * 0.04));
    float warpedTheta = theta + 0.15 * (warp.x - 0.5) * bloom;

    float petalShape = pow(abs(cos(n * 0.5 * warpedTheta)), 0.5 + 1.5 * (1.0 - bloom));
    float rMax = mix(0.06, 0.42, bloom) * (0.7 + 0.5 * petalShape);

    float d = r - rMax;
    float fill = smoothstep(0.015, -0.015, d);

    float depthGrad = clamp((rMax - r) / max(rMax, 0.001), 0.0, 1.0);
    float tex = fbm(uv * 8.0 + warp * 2.0);
    float hue = fract(0.02 * theta + depthGrad * 0.3 + tex * 0.15);
    vec3 petalCol = palette(hue, vec3(0.85, 0.45, 0.4), vec3(0.15, 0.3, 0.35), vec3(1.0, 1.0, 0.7), vec3(0.0, 0.1, 0.35));
    petalCol = mix(petalCol * 0.6, petalCol, depthGrad);

    vec3 centerCol = vec3(0.95, 0.72, 0.2) * (0.8 + 0.4 * tex);
    float centerMask = smoothstep(0.09, 0.03, r) * (0.3 + 0.7 * bloom);
    vec3 flowerCol = mix(petalCol, centerCol, centerMask);

    vec3 bg = mix(vec3(0.04, 0.06, 0.05), vec3(0.08, 0.1, 0.08), 0.5 + 0.5 * uv.y);
    vec3 col = mix(bg, flowerCol, fill);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

vec2 hash22(vec2 p) {
    return vec2(hash21(p), hash21(p + 17.17));
}

float voronoi(vec2 p) {
    vec2 ip = floor(p);
    vec2 fp = fract(p);
    float minD = 1.5;
    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            vec2 neighbor = vec2(float(x), float(y));
            vec2 point = hash22(ip + neighbor);
            vec2 diff = neighbor + point - fp;
            minD = min(minD, length(diff));
        }
    }
    return minD;
}

float petalMask(vec2 uv, float rot, float len, float wid) {
    float s = sin(rot);
    float c = cos(rot);
    vec2 p = vec2(c * uv.x + s * uv.y, -s * uv.x + c * uv.y);
    p.y -= len * 0.5;
    vec2 q = vec2(p.x / wid, p.y / len);
    float d = length(q) - 0.5;
    return smoothstep(0.04, -0.04, d);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float bloom = smoothstep(0.0, 1.0, 0.5 + 0.5 * sin(iTime * 0.3));

    vec3 col = mix(vec3(0.03, 0.05, 0.04), vec3(0.07, 0.09, 0.07), 0.5 + 0.5 * uv.y);

    const int LAYERS = 5;
    const int PETALS = 6;
    for (int L = 0; L < LAYERS; L++) {
        float fl = float(L);
        float layerBloom = clamp(bloom * float(LAYERS) - fl, 0.0, 1.0);
        layerBloom = smoothstep(0.0, 1.0, layerBloom);
        if (layerBloom <= 0.001) continue;

        float len = mix(0.05, 0.38, layerBloom) * (1.0 - fl * 0.08);
        float wid = mix(0.03, 0.1, layerBloom);
        float ringRot = fl * 0.35 + iTime * 0.05;

        for (int i = 0; i < PETALS; i++) {
            float ang = float(i) / float(PETALS) * 6.28318 + ringRot;
            float m = petalMask(uv, ang, len, wid);
            if (m <= 0.001) continue;

            vec2 local = uv * (3.0 + fl) + vec2(fl * 5.0, ang * 2.0);
            float vc = voronoi(local);
            float hue = fract(0.55 + fl * 0.05 - vc * 0.2);
            vec3 petalCol = mix(vec3(0.9, 0.3, 0.45), vec3(1.0, 0.85, 0.55), hue);
            petalCol *= 0.7 + 0.3 * (1.0 - vc);

            col = mix(col, petalCol, m * layerBloom * 0.85);
        }
    }

    float r = length(uv);
    float centerMask = smoothstep(0.1, 0.04, r) * bloom;
    col = mix(col, vec3(0.95, 0.78, 0.25), centerMask);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
